#!/usr/bin/env node
/**
 * Pinned Functions vendor blobs are duplicated per 3.5 codebase so each
 * deploy stays self-contained. functions/vendor is the source of truth;
 * sibling copies must be byte-identical or deploys silently diverge.
 * (Synced manifests for entitlements/signal-envelope-contracts/functions-shared
 * are regenerated by scripts/sync-functions-vendors.mjs and pinned by hash
 * in the deploy artifact instead — see verify-staging-functions-artifact.)
 */
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(
  process.env.FUNCTIONS_CI_FIXTURE_ROOT ?? join(dirname(fileURLToPath(import.meta.url)), "..", ".."),
);
const SIBLINGS = ["functions-identity", "functions-sync", "functions-media"];

const sha256 = (path) => createHash("sha256").update(readFileSync(path)).digest("hex");

const failures = [];
const expectIdentical = (canon, mirror) => {
  let canonHash;
  try {
    canonHash = sha256(join(repoRoot, canon));
  } catch {
    failures.push(`canonical pinned blob missing: ${canon}`);
    return;
  }
  let mirrorHash;
  try {
    mirrorHash = sha256(join(repoRoot, mirror));
  } catch {
    failures.push(`pinned blob missing in ${mirror} (npm ci + artifact verifier need it)`);
    return;
  }
  if (canonHash !== mirrorHash) {
    failures.push(`pinned blob drifted: ${mirror} differs from ${canon}`);
  }
};

for (const sibling of SIBLINGS) {
  for (const file of [
    "vendor/openburnbar/brace-expansion-cjs.tgz",
    "vendor/openburnbar/brace-expansion-cjs/index.js",
    "vendor/openburnbar/brace-expansion-cjs/package.json",
    "vendor/openburnbar/brace-expansion-cjs/README.md",
  ]) {
    expectIdentical(join("functions", file), join(sibling, file));
  }
}

// domain-core-wasm ships only where a codebase declares it (admin + sync).
const wasmDir = join("functions", "vendor", "openburnbar", "domain-core-wasm");
for (const file of readdirSync(join(repoRoot, wasmDir)).sort()) {
  expectIdentical(join(wasmDir, file), join("functions-sync", "vendor", "openburnbar", "domain-core-wasm", file));
}

if (failures.length > 0) {
  console.error("Functions vendor-pin verification failed:");
  for (const failure of failures) console.error(`  - ${failure}`);
  process.exit(1);
}
console.log("PASS: Functions vendor pins are byte-identical across codebases.");
